module.exports=[54674,46602,54544,a=>{"use strict";var b=a.i(7997);a.s(["JsonLd",0,function({data:a}){return(0,b.jsx)("script",{type:"application/ld+json",dangerouslySetInnerHTML:{__html:JSON.stringify(a)}})}],54674);var c=a.i(2289),d=a.i(41648),e=a.i(3144),f=a.i(72953),g=a.i(22026);let h={"privacy-policy":d.default,"refund-policy":e.default,"shipping-policy":f.default,"accessibility-statement":c.default,"terms-of-use":g.default},i=[{key:"privacy-policy",title:"隐私政策",description:"数易赋能隐私政策 — 我们如何收集、使用与保护您的个人信息。",path:"/privacy-policy"},{key:"refund-policy",title:"退款政策",description:"数易赋能退款政策 — 会员与数字商品的退款规则说明。",path:"/refund-policy"},{key:"shipping-policy",title:"配送政策",description:"数易赋能配送政策 — 实体商品配送与交付说明。",path:"/shipping-policy"},{key:"accessibility-statement",title:"无障碍声明",description:"数易赋能无障碍声明 — 我们对网站与应用无障碍使用的承诺。",path:"/accessibility-statement"},{key:"terms-of-use",title:"使用条款",description:"数易赋能使用条款 — 使用网站与 App 服务的规则与约定。",path:"/terms-of-use"}];a.s(["getLegalDocument",0,function(a){return h[a]},"getLegalPageMeta",0,function(a){let b=i.find(b=>b.key===a);if(!b)throw Error(`Unknown legal page: ${a}`);return b},"legalPages",0,i],46602);var j=a.i(92814);[...i.map(a=>({path:a.path,changeFrequency:"yearly",priority:.4}))];let k={home:{title:j.siteTagline,description:"数易赋能 — 透过数字生命、姓名学与东方智慧，帮助您更了解自己与他人。",path:"/"},about:{title:"关于我们",description:"了解数易赋能的品牌故事、价值使命与团队。",path:"/about-us"},contact:{title:"联系我们",description:"联系数易赋能团队，获取产品与服务支持。",path:"/contact-us"},portfolio:{title:"产品服务",description:"探索数易赋能的数字生命、姓名学、塔罗与东方占卜等服务。",path:"/portfolio"},shopping:{title:"商店",description:"数易赋能官方商店与精选产品。",path:"/shopping"},shop:{title:"官方商店",description:"浏览数易赋能 PlenorHub 官方商品，会员享商城优惠。",path:"/shop"},celue:{title:"测算",description:"选择数字生命等测算服务，输入基本资料即可获得简版预览。完整解读请前往数易 App。",path:"/celue"},membership:{title:"会员方案",description:"了解数易赋能基础、精英与至尊会员价格及权益。完整开通与管理请前往数易 App。",path:"/membership"}};a.s(["breadcrumbJsonLd",0,function(a){return{"@context":"https://schema.org","@type":"BreadcrumbList",itemListElement:a.map((a,b)=>({"@type":"ListItem",position:b+1,name:a.name,item:`${j.siteUrl}${"/"===a.path?"":a.path}`}))}},"organizationJsonLd",0,function(){return{"@context":"https://schema.org","@type":"Organization",name:j.organization.name,url:j.organization.url,email:j.organization.email,logo:j.organization.logo}},"pageSeo",0,k,"webPageJsonLd",0,function(a){return{"@context":"https://schema.org","@type":"WebPage",name:a.title,description:a.description,url:`${j.siteUrl}${"/"===a.path?"":a.path}`,inLanguage:"zh-CN",isPartOf:{"@type":"WebSite",name:j.siteName,url:j.siteUrl}}},"websiteJsonLd",0,function(){return{"@context":"https://schema.org","@type":"WebSite",name:j.siteName,url:j.siteUrl,inLanguage:"zh-CN"}}],54544)},2289,(a,b,c)=>{b.exports={title:"无障碍声明",path:"/accessibility-statement",wpSlug:"accessibility-statement",capturedAt:"2026-08-11",blocks:[{type:"heading",text:"无障碍声明"},{type:"heading",text:"本声明更新于2025年5月31日。"},{type:"heading",text:"我们《数易赋能》团队致力于让所有用户，包括有视觉、听觉、认知或行动障碍的用户，都能够顺利访问并使用我们的产品与服务。为此，我们持续优化 App 与网站的设计与内容，力求遵循国际无障碍标准（如《Web 内容无障碍指南 WCAG 2.1》），以提升用户体验和包容性。"},{type:"heading",text:"我们对无障碍的定义"},{type:"paragraph",text:"一个具备无障碍功能的网站，能够让有障碍的访客以与其他用户相同或相近的便利与体验，顺利浏览网站内容。这一目标可通过操作系统本身的辅助功能，或借助各类辅助技术（如屏幕阅读器、语音控制、放大工具等）来实现。"},{type:"heading",text:"我们所采取的措施包括但不限于："},{type:"paragraph",text:"使用清晰的排版与对比度，以提高可读性 为图像与按钮提供文字说明（Alt Text） 简化页面结构，支持屏幕阅读器操作 提供语言、颜色及交互方式上的可选项（例如深色模式等） 未来版本将逐步加入更多辅助功能（如语音支持、无障碍导航等）"},{type:"heading",text:"关于第三方部分不符合无障碍标准的声明"},{type:"paragraph",text:"尽管我们致力于遵循各项无障碍设计标准，但由于部分页面中包含第三方提供的内容（如嵌入式插件、外部链接、广告组件等），这些内容的可访问性可能未完全符合无障碍规范。我们无法完全控制此类第三方内容的可访问性表现，但会持续评估其影响，并在可行的情况下寻求替代方案或改善措施，以提升整体用户体验。如您在浏览过程中因这些内容而遇到障碍，欢迎通过我们的联系方式与我们反馈，我们将尽力协助解决。"},{type:"paragraph",text:"如果您在使用本网站过程中遇到无障碍相关的问题，或需要进一步的协助，欢迎您随时联系本组织的无障碍协调员："},{type:"paragraph",text:"如果您在使用本网站过程中遇到无障碍相关的问题，或需要进一步的协助，欢迎您随时联系本组织的无障碍协调员： [无障碍协调员姓名] [联系电话] [电子邮件地址] 如有其他联系方式，也请在此处填写（如适用）。 我们将尽力协助您解决问题，并持续优化我们的无障碍服务。"}]}},41648,(a,b,c)=>{b.exports={title:"隐私政策",path:"/privacy-policy",wpSlug:"privacy-policy",capturedAt:"2026-08-11",blocks:[{type:"heading",text:"隐私政策 Privacy Policy"},{type:"heading",text:"前言 Introduction"},{type:"heading",text:"感谢您使用我们的数易数字人生软件/网页（以下简称“服务”）。我们深知个人隐私对您的重要性，并致力于保护您的个人信息。本隐私协议（以下简称“协议”）旨在向您阐述在您使用服务过程中，我们如何收集、使用、披露和保护您的个人信息。请您在使用服务前仔细阅读本协议，确保您充分理解和同意我们的隐私保护措施。"},{type:"heading",text:'Thank you for using the Shuyi Digital Life software/website (hereinafter referred to as the "Service"). We value the importance of your personal privacy and are committed to protecting your personal information. This Privacy Policy (hereinafter referred to as the "Policy") explains how we collect, use, disclose, and safeguard your personal information when you use our Service. Please read this Policy carefully before using the Service to ensure that you fully understand and agree to our privacy protection measures.'},{type:"heading",text:"我们收集的信息 Information We Collect"},{type:"paragraph",text:"1. 个人信息 Personal Information 当您使用我们的服务时，我们可能会收集您的个人信息，包括但不限于： – 注册信息： 姓名、出生日期、性别、联系方式等。 – 使用信息： 您使用服务时产生的信息，例如您的设备信息、IP地址、浏览记录等。 When you use our Service, we may collect the following personal information, including but not limited to: – Registration information: name, date of birth, gender, contact details, etc. – Usage information: data generated during your use of the Service, such as device information, IP address, and browsing history. 2. 非个人信息 Non-Personal Information 我们还可能收集非个人信息，例如设备型号、操作系统版本、浏览器类型等。这些信息无法直接识别您的个人身份。 另外，我们无权限获取您的测算信息，若有任何数据丢失，我们无法恢复相关数据。 We may also collect non-personal information, such as device model, operating system version, and browser type. Such information does not directly identify your personal identity. Additionally, we do not have access to your fortune-calculation results; therefore, in the event of data loss, we are unable to restore such data."},{type:"heading",text:"我们如何使用您的信息 How We Use Your Information"},{type:"paragraph",text:"提供服务 Providing Services ： 根据您提供的信息为您进行数字人生测算、算命、占卜等服务。 改善服务 Improving Services ： 分析您的使用情况和反馈，改进我们的服务质量和用户体验。 个性化推荐 Personalization ： 根据您的兴趣和偏好，向您推荐相关内容和服务。 营销推广 Marketing & Promotions ： 在您同意的情况下，向您发送有关我们服务的最新资讯、优惠活动等信息。 法律义务 Legal Compliance ： 遵守适用的法律法规和监管要求。"},{type:"heading",text:"我们如何披露您的信息 How We Disclose Your Information"},{type:"paragraph",text:"第三方服务提供商 Third-Party Service Providers ： 我们可能会与第三方服务提供商共享您的信息，以便他们为我们提供技术支持、数据分析、营销推广等服务。 法律义务 Legal Obligations ： 在法律法规要求或政府部门要求的情况下，我们可能会披露您的信息。 合并、收购等 Business Transactions ： 如果我们涉及合并、收购或破产等情况，您的信息可能会转移给相关第三方。"},{type:"heading",text:"我们如何保护您的信息 How We Protect Your Information"},{type:"paragraph",text:"我们采取合理且必要的技术和管理措施，防止您的信息遭到未经授权的访问、使用、披露、更改或破坏。例如： 数据加密与存储保护 严格的访问权限控制 定期的安全监测与漏洞修复 We implement appropriate technical and organizational measures to protect your information against unauthorized access, use, disclosure, alteration, or destruction. For example: Encryption and secure storage of data Strict access control measures Regular security monitoring and vulnerability patching"},{type:"heading",text:"您的权利 Your Rights"},{type:"paragraph",text:"根据适用的法律，您享有以下权利： 访问和更正：您可以访问或修改您的个人信息。 删除权：在符合法律要求的情况下，您可以请求删除您的个人信息。 撤回同意：您有权随时撤回对某些信息处理的同意。 Under applicable laws, you have the following rights: Access and Correction: You may access or correct your personal information. Right to Deletion: You may request deletion of your personal information under certain legal conditions. Withdrawal of Consent: You may withdraw your consent to certain processing activities at any time."},{type:"heading",text:"政策更新 Policy Updates"},{type:"paragraph",text:"我们可能会根据法律法规或服务需求，不时更新本隐私政策。更新后的内容将通过适当方式通知您，并自发布之日起生效。 We may update this Privacy Policy from time to time in accordance with legal or service requirements. Updated versions will be communicated to you through appropriate means and will take effect from the date of publication."},{type:"heading",text:"联系我们 Contact Us"},{type:"paragraph",text:"如果您对本隐私政策或个人信息的处理有任何疑问，请通过以下方式联系我们： 电子邮箱：shuyi.fn@gmail.com If you have any questions about this Privacy Policy or our handling of your personal information, please contact us at: Email: shuyi.fn@gmail.com"}]}},3144,(a,b,c)=>{b.exports={title:"退款政策",path:"/refund-policy",wpSlug:"refund-policy",capturedAt:"2026-08-11",blocks:[{type:"heading",text:"退款政策 Refund Policy"},{type:"heading",text:"声明 A Legal Disclaimer"},{type:"heading",text:"我们致力于保障用户的合法权益，并提供合理、公正的退款机制。然而，我们保留在不另行通知的情况下，根据适用法规、政策更新、突发状况或国家法律的变更，调整退款政策的权利。所有调整将在不损害消费者基本权益的前提下执行，并以保障用户体验与平台运营平衡为原则。 若您对退款相关政策有任何疑问，欢迎随时联系客户服务团队，我们将尽力协助处理。"},{type:"heading",text:"We are committed to protecting users’ legitimate rights and providing a fair and reasonable refund mechanism. However, we reserve the right to adjust this policy without prior notice in accordance with applicable laws, policy updates, unforeseen circumstances, or legal changes. All adjustments will be made without compromising basic consumer rights, and will be guided by the principle of balancing user experience with platform operations. If you have any questions about this policy, please feel free to contact our customer service team."},{type:"heading",text:"基础框架 The Basic Framework"},{type:"paragraph",text:"本退款政策参考并遵循以下规范： Apple App Store 与 Google Play 开发者政策 数字产品行业标准（即时交付、不可退回） 订阅服务常见规则（自动续订、取消与退款条件） 全球消费者权益保护法规（如 GDPR 等） This Refund Policy is based on and follows: Apple App Store and Google Play developer policies Digital product industry standards (instant delivery, non-returnable) Subscription service practices (auto-renewal, cancellation, refund conditions) Global consumer protection laws (e.g., GDPR and other applicable regulations)"},{type:"heading",text:"条款 The Clause"},{type:"paragraph",text:"我们致力于为用户提供高质量的数字服务和优质的使用体验。如果您对所购买的服务不满意，您可以根据以下条款申请退款。"},{type:"paragraph",text:"一、数字产品与服务 Digital Products & Services 数字类产品（如个性化解读、分析报告、下载资源等）一经交付，通常视为最终交易，不支持退款。 以下情况可申请退款：重复付款、无法正常使用的技术问题、系统/平台错误扣款。 Digital products (such as personalized readings, reports, downloadable resources) are generally considered final once delivered and are non-refundable. Refunds may be granted under special circumstances: duplicate payments, technical issues preventing access, or billing errors."},{type:"paragraph",text:"二、会员与订阅服务 Membership & Subscriptions 首次购买：在 7 天内 申请退款且未使用任何专属功能，可酌情处理。 续费订单：自动续订成功后不予退款，请提前取消。 降级会员：降级不会退还差价。 For first-time purchases: Refund requests within 7 days may be considered if no membership features have been used. Renewals are non-refundable once processed; please cancel beforehand. Downgrading membership will not trigger partial refunds."},{type:"paragraph",text:"三、实物商品 Physical Products 可退条件：商品必须保持完好，未使用，原包装完整。通常需在 7–14 天内 申请。 不可退：定制/个性化商品、因个人原因损坏的商品、超过退货期限。 退货运费：质量问题由我们承担，个人原因退货由用户承担。 Eligible for return: Items must be unused, undamaged, and in original packaging. Requests should be made within 7–14 days. Non-returnable: Customized items, user-damaged items, or overdue returns. Return shipping: Covered by us if due to product defects; otherwise borne by the user."},{type:"paragraph",text:"四、特殊情况 Special Circumstances 预售/定制服务：确认后不可退款，除非存在严重质量或履约问题。 促销/清仓商品：通常不支持退款或退换。 不可抗力：因自然灾害、政策、清关延误等造成的影响，不构成全额退款义务。 Pre-orders/customized services are non-refundable once confirmed, except for major quality or fulfillment issues. Promotional/clearance items are generally non-refundable. Force majeure (e.g., natural disasters, customs delays, regulatory restrictions) does not guarantee full refunds."},{type:"paragraph",text:"五、退款流程 Refund Process 申请方式：📧 shuyi.fn@gmail.com 请提供：注册邮箱、订单号（Apple/Google 订单号）、退款原因与凭证。 客服将在 3–5 个工作日 内回复； 审核通过后，退款将在 7 个工作日 内原路退回。 To apply: Email shuyi.fn@gmail.com with your registered email, order ID (Apple/Google), reason, and supporting evidence. Customer service will respond within 3–5 business days; Approved refunds will be returned to the original payment method within 7 business days."},{type:"paragraph",text:"六、审核与限制 Review & Limitations 频繁退款或恶意行为账户可能被限制服务。 若发现欺诈、滥用政策等情况，我们有权拒绝退款并追究责任。 Accounts with frequent or malicious refund requests may face service restrictions. Fraudulent activity or abuse of this policy may result in denial of refunds and potential legal action."}]}},72953,(a,b,c)=>{b.exports={title:"配送政策",path:"/shipping-policy",wpSlug:"shipping-policy",capturedAt:"2026-08-11",blocks:[{type:"heading",text:"配送政策 Shipping & Delivery Policy"},{type:"heading",text:"声明 A Legal Disclaimer"},{type:"heading",text:"我们致力于保障用户的合法权益，并提供清晰透明的配送标准。然而，我们保留在不另行通知的情况下，根据适用法规、政策更新、突发状况或国家法律的变更，调整本配送政策的权利。所有调整将在不损害消费者基本权益的前提下执行，并以保障用户体验与平台运营平衡为原则。若您对配送相关政策有任何疑问，欢迎随时联系客户服务团队，我们将尽力协助处理。"},{type:"heading",text:"We are committed to protecting users’ rights and providing clear and transparent delivery standards. However, we reserve the right to adjust this policy without prior notice due to applicable laws, policy changes, unforeseen circumstances, or legal amendments. Any adjustments will be implemented without compromising consumers’ fundamental rights and will aim to balance user experience with platform operations. If you have questions, please contact our customer service team."},{type:"heading",text:"基础框架 The Basic Framework"},{type:"paragraph",text:"本配送政策参考并遵循以下行业与平台规范： 主流电商与跨境物流实践（时效、物流追踪、退换规则）； 各国进出口与海关规定（关税、增值税及清关程序）； 数字产品即时交付特性（无法物理退回）； 用户通知与隐私保护合规要求。 This Delivery Policy is based on and follows: Mainstream e-commerce and cross-border logistics practices (timelines, tracking, return rules); International import/export and customs regulations (duties, VAT, clearance procedures); The nature of digital product delivery (instant, non-returnable); Compliance with user notification and privacy requirements."},{type:"heading",text:"条款 The Clause"},{type:"paragraph",text:"我们致力于为用户提供高质量的数字服务和优质的使用体验。如果您对所购买的服务不满意，您可以根据以下条款申请退款。"},{type:"paragraph",text:"一、交付范围与品类 Delivery Scope & Categories 数字订阅与电子服务 Digital Subscriptions & Services 发货时效：下单后自动交付，最迟 12 小时内完成激活/开通。 交付方式：账号开通、解锁内容、下载链接或激活码等。 Delivery time: Instant fulfillment upon purchase, within 12 hours at the latest. Delivery method: Account activation, unlocked content, download links, or activation codes. 服装与实体产品 Apparel & Physical Goods 配送时效（不含处理时间）： 快递：3–5 个工作日 普通：5–7 个工作日 国际：7–14 个工作日（以目的国清关与派送为准） Delivery timeline (excluding processing time): Express: 3–5 business days Standard: 5–7 business days International: 7–14 business days (depending on customs and local delivery)"},{type:"paragraph",text:"二、订单处理与发货 Order Processing & Dispatch 处理时间：通常于 24–48 小时 内完成，周末/节假日顺延。 截单时间：每日 15:00 (GMT+8) 前订单优先处理，逾时顺延。 分包发货：同一订单可能拆分为多个包裹发货。 Processing time: Typically completed within 24–48 hours, excluding weekends/holidays. Cut-off time: Orders placed before 3:00 PM (GMT+8) are prioritized; later orders processed next business day. Split shipments: Orders with multiple items may be shipped in separate parcels."},{type:"paragraph",text:"三、运费与费用 Shipping Costs & Charges 运费：以结算页显示为准（可能因地区、重量、活动免邮而不同）。 关税与税费：国际配送可能产生关税或增值税，由收件人承担。 Shipping fees: As displayed at checkout (may vary by region, weight, or promotions). Duties & taxes: International orders may incur import duties or VAT, payable by the recipient."},{type:"paragraph",text:"四、地址与配送失败 Address & Delivery Failure 地址错误：因收件信息错误导致投递失败，额外费用由用户承担。 无人签收：承运商通常会尝试 1–3 次投递或留取自提通知，超时未取视为买家原因退回。 Incorrect address: Any additional costs from failed delivery due to incorrect info will be borne by the buyer. Missed delivery: Carriers may attempt delivery 1–3 times or leave a pickup notice; unclaimed packages may be returned at buyer’s expense."},{type:"paragraph",text:"五、物流追踪与通知 Tracking & Notifications 追踪：发货后提供运单号与查询链接。 异常协助：若超过 72 小时 无更新或逾期未达，请联系客户服务。 Tracking: Tracking numbers and links provided after dispatch. Assistance: If no updates appear within 72 hours or shipment is delayed, contact customer service."},{type:"paragraph",text:"五、物流追踪与通知 Tracking & Notifications 追踪：发货后提供运单号与查询链接。 异常协助：若超过 72 小时 无更新或逾期未达，请联系客户服务。 Tracking: Tracking numbers and links provided after dispatch. Assistance: If no updates appear within 72 hours or shipment is delayed, contact customer service."},{type:"paragraph",text:"六、商品签收与验货 Receipt & Inspection 建议：签收时检查外包装与商品完好。 损坏/少件：请在 48 小时内 提交照片凭证以便理赔。 Recommendation: Inspect packaging and items upon receipt. Damage/missing items: Report with photos within 48 hours for claims to be processed."},{type:"paragraph",text:"七、预售与定制商品 Pre-orders & Customized Items 预售商品：发货时间以商品页说明为准，可能合单延迟发货。 定制商品：因生产工期较长，发货时间以确认信息为准。 Pre-orders: Shipping timeline based on product page; orders may be delayed until all items are ready. Customized items: Production time may extend delivery; timeline confirmed at purchase."},{type:"paragraph",text:"八、不可抗力 Force Majeure 因政策调整、自然灾害、清关管制、航班/船运延误等不可抗力造成的延迟，不视为违约。 Delays caused by force majeure events (e.g., regulatory changes, natural disasters, customs holds, transport delays) are not considered breaches of this policy."},{type:"paragraph",text:"九、与退款/售后之衔接 Relation to Refund Policy 配送相关退款/售后问题以《退款政策》为准。 若因物流遗失、破损或错发，核实后将按退款/补发流程处理。 Refunds or after-sales issues related to delivery are subject to the Refund Policy. Lost, damaged, or misdelivered items will be processed according to refund/replacement procedures after verification."},{type:"paragraph",text:"十、客服联系方式 Customer Support 📧 邮箱 Email: shuyi.fn@gmail.com 服务时间：工作日 10:00–18:00 (GMT+8) Business hours: Weekdays 10:00–18:00 (GMT+8)"}]}},22026,(a,b,c)=>{b.exports={title:"使用条款",path:"/terms-of-use",wpSlug:"%e4%bd%bf%e7%94%a8%e6%9d%a1%e6%ac%be",capturedAt:"2026-08-11",blocks:[{type:"heading",text:"使用协议"},{type:"heading",text:"A Legal Disclaimer"},{type:"heading",text:"The explanations and information provided on this page are only general and high-level explanations and information on how to write your own document of Terms & Conditions. You should not rely on this article as legal advice or as recommendations regarding what you should actually do, because we cannot know in advance what are the specific terms you wish to establish between your business and your customers and visitors. We recommend that you seek legal advice to help you understand and to assist you in the creation of your own Terms & Conditions."},{type:"heading",text:"Privacy Policy - the basics"},{type:"heading",text:"Having said that, Terms and Conditions (“T&C”) are a set of legally binding terms defined by you, as the owner of this website. The T&C set forth the legal boundaries governing the activities of the website visitors, or your customers, while they visit or engage with this website. The T&C are meant to establish the legal relationship between the site visitors and you as the website owner."},{type:"heading",text:"T&C should be defined according to the specific needs and nature of each website. For example, a website offering products to customers in e-commerce transactions requires T&C that are different from the T&C of a website only providing information (like a blog, a landing page, and so on)."},{type:"heading",text:"T&C provide you as the website owner the ability to protect yourself from potential legal exposure, but this may differ from jurisdiction to jurisdiction, so make sure to receive local legal advice if you are trying to protect yourself from legal exposure."},{type:"heading",text:"What to include in the Privacy Policy"},{type:"heading",text:"Generally speaking, T&C often address these types of issues: Who is allowed to use the website; the possible payment methods; a declaration that the website owner may change his or her offering in the future; the types of warranties the website owner gives his or her customers; a reference to issues of intellectual property or copyrights, where relevant; the website owner’s right to suspend or cancel a member’s account; and much much more."},{type:"paragraph",text:"To learn more about this, check out our article ” Article Link 🔗"}]}}];

